    <script>
      const form = document.getElementById("quiz-form");
      const result = document.getElementById("quiz-result");

      const answerKey = {
        question1: ["HTML", "CSS"],
        question2: ["TypeScript", "Java", "C#"],
        question3: ["SQL", "PL/SQL"]
      };

      function getCheckedValues(questionName) {
        return Array.from(form.querySelectorAll(`input[name="${questionName}"]:checked`))
          .map((input) => input.value)
          .sort();
      }

      function isCorrectSelection(questionName) {
        const selected = getCheckedValues(questionName);
        const correct = [...answerKey[questionName]].sort();

        return (
          selected.length === correct.length &&
          selected.every((value, index) => value === correct[index])
        );
      }

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const questionNames = Object.keys(answerKey);
        const answeredCount = questionNames.filter((name) => getCheckedValues(name).length > 0).length;

        if (answeredCount !== questionNames.length) {
          result.classList.add("is-visible");
          result.textContent = "Please select at least one answer for each question before submitting.";

          const firstEmptyQuestion = questionNames.find((name) => getCheckedValues(name).length === 0);
          const firstUncheckedInput = form.querySelector(`input[name="${firstEmptyQuestion}"]`);

          if (firstUncheckedInput) {
            firstUncheckedInput.focus();
          }

          return;
        }

        const correctCount = questionNames.filter(isCorrectSelection).length;
        const feedbackItems = questionNames
          .map((name, index) => {
            const status = isCorrectSelection(name) ? "Correct" : "Incorrect";
            return `<li>Question ${index + 1}: ${status}</li>`;
          })
          .join("");

        result.classList.add("is-visible");
        result.innerHTML = `You scored ${correctCount} out of ${questionNames.length}.<ul class="feedback-list">${feedbackItems}</ul>`;
      });
    </script>
